export const listPurchasesQueryLimitDefault = 20;
export const listPurchasesQueryLimitMax = 100;

export const listPurchasesQueryOffsetDefault = 0;
export const listPurchasesQueryOffsetMin = 0;



export const ListPurchasesQueryParams = zod.object({
  "customer_id": zod.coerce.string().optional(),
  "date_from": zod.date().optional(),
  "date_to": zod.date().optional(),
  "search": zod.coerce.string().max(listPurchasesQuerySearchMax).optional(),
  "limit": zod.coerce.number().int().min(1).max(listPurchasesQueryLimitMax).default(listPurchasesQueryLimitDefault),
  "offset": zod.coerce.number().int().min(listPurchasesQueryOffsetMin).default(listPurchasesQueryOffsetDefault)
})

