/**
 * Atomically saves purchase items and, for Khata only, exactly one ledger credit. Identical retries return the original purchase; changed payloads with the same key return 409. Cash/UPI do not repay existing debt. No split payments or stock deduction.
 */
export const createPurchaseBodyCustomerIdMax = 36;

export const createPurchaseBodyItemsItemProductIdMax = 36;

export const createPurchaseBodyItemsItemProductNameMax = 150;

export const createPurchaseBodyItemsItemQuantityRegExp = new RegExp('^\\d{1,9}(\\.\\d{1,3})?$');
export const createPurchaseBodyItemsItemUnitMax = 30;

export const createPurchaseBodyItemsItemUnitPriceRegExp = new RegExp('^\\d{1,12}(\\.\\d{1,2})?$');
export const createPurchaseBodyItemsMax = 100;

export const createPurchaseBodyNotesMax = 1000;

export const createPurchaseBodyIdempotencyKeyMin = 8;
export const createPurchaseBodyIdempotencyKeyMax = 128;



export const CreatePurchaseBody = zod.object({
  "customer_id": zod.string().min(1).max(createPurchaseBodyCustomerIdMax),
  "payment_method": zod.enum(['cash', 'upi', 'khata']),
  "items": zod.array(zod.object({
  "product_id": zod.string().max(createPurchaseBodyItemsItemProductIdMax).nullish(),
  "product_name": zod.string().max(createPurchaseBodyItemsItemProductNameMax).optional().describe('Required for custom items; catalog name is snapshotted when product_id is provided'),
  "quantity": zod.string().regex(createPurchaseBodyItemsItemQuantityRegExp).describe('Positive decimal string'),
  "unit": zod.string().min(1).max(createPurchaseBodyItemsItemUnitMax),
  "unit_price": zod.string().regex(createPurchaseBodyItemsItemUnitPriceRegExp)
})).min(1).max(createPurchaseBodyItemsMax),
  "notes": zod.string().max(createPurchaseBodyNotesMax).optional(),
  "idempotency_key": zod.string().min(createPurchaseBodyIdempotencyKeyMin).max(createPurchaseBodyIdempotencyKeyMax)
})

